import React from 'react';
import { HiUsers } from 'react-icons/hi';
import { ImTree } from 'react-icons/im';

interface CourseCardProps {
  cardData: {
    heading: string;
    description: string;
    level: string;
    lessionNumber: number;
  };
  currentCard: string;
  setCurrentCard: (heading: string) => void;
}

const CourseCard: React.FC<CourseCardProps> = ({ cardData, currentCard, setCurrentCard }) => {
  const isActive = currentCard === cardData.heading;

  return (
    <div
      className={`h-full rounded-lg transition-all duration-200 cursor-pointer ${
        isActive
          ? 'bg-white text-richblack-800 shadow-lg transform hover:-translate-y-1'
          : 'bg-richblack-800 text-richblack-25 hover:bg-richblack-700'
      }`}
      onClick={() => setCurrentCard(cardData.heading)}
    >
      <div className="p-6 border-b border-dashed border-richblack-400">
        <h3 className={`text-xl font-semibold mb-4 ${isActive ? 'text-richblack-800' : ''}`}>
          {cardData.heading}
        </h3>
        <p className={`${isActive ? 'text-richblack-500' : 'text-richblack-400'}`}>
          {cardData.description}
        </p>
      </div>

      <div className={`flex justify-between items-center p-6 ${
        isActive ? 'text-blue-500' : 'text-richblack-300'
      }`}>
        <div className="flex items-center gap-2">
          <HiUsers className="text-lg" />
          <span>{cardData.level}</span>
        </div>
        <div className="flex items-center gap-2">
          <ImTree className="text-lg" />
          <span>{cardData.lessionNumber} Lessons</span>
        </div>
      </div>
    </div>
  );
}

export default CourseCard;
